import {mountApplicationShell} from '../forge-shell/shell.mjs';import {deploymentPath} from '../deployment.mjs';
export function mountProjectShell({root,status,project,revision,library,creation,imports,templates,instrument,electronics,history,comparison,measurements,documents,metadataForm,onLibrary,onView,activeView='library',dirty=false,pending=false}={}){
 const doc=root.ownerDocument,e=(tag,text)=>{const n=doc.createElement(tag);if(text)n.textContent=text;return n;},props=e('aside');props.className='forge-pro-detail';const caption=e('h2','Properties'),inspection=e('div');inspection.setAttribute('aria-live','polite');props.append(caption,inspection);if(metadataForm)props.append(metadataForm);
 const help=e('div');help.append(e('h2','Learn Forge projects'),e('p','Free design is local. Cloud saves are explicit durable revisions; Undo/Redo in the design editor is separate editing history. Importing retains the local original. Templates create independent projects. Measurements are observations, not response-model inputs. Technical Build Sheets freeze one revision and its recorded measurements.'),e('p','Professional tools are available during development through Forge Pro Preview. Availability may change. No billing or public Circuit Passport is offered.'));
 const createDetails=e('details');createDetails.append(e('summary','New project'));createDetails.append(creation);createDetails.open=!project&&!library.querySelector('li strong');library.append(createDetails,imports);
 const empty=e('section');empty.append(e('h2','Personal templates'),e('p','Save a revision as a personal template from a project.'));templates ||= empty;
 const views=[{id:'library',title:'Projects',node:library},{id:'templates',title:'Templates',node:templates}];if(project)views.push({id:'instrument',title:'Instrument',node:instrument},{id:'electronics',title:'Electronics',node:electronics},...(history?[{id:'revisions',title:'Revisions',node:history}]:[]),...(comparison?[{id:'compare',title:'Compare',node:comparison,disabled:comparison.dataset.comparable==='false',reason:'Save at least two compatible revisions to compare.'}]:[]),...(measurements?[{id:'measurements',title:'Measurements',node:measurements}]:[]),...(documents?[{id:'document',title:'Document',node:documents}]:[]));
 const commands=[],browser=[];
 let shell;function showProperties(view){caption.textContent='Properties / '+({library:'Library',templates:'Templates',instrument:'Instrument',electronics:'Electronics',revisions:'Revision',compare:'Comparison',measurements:'Measurement',document:'Document'}[view]||'Context');inspection.replaceChildren();if(metadataForm)metadataForm.hidden=view!=='instrument';if(view==='instrument')inspection.append(e('p','User-entered instrument metadata. Save a new cloud revision to commit changes.'));else inspection.append(e('p',project?project.title+' · V'+revision.sequence+' · '+revision.name:'Your private instrument projects.'));shell?.setSelection({kind:view,id:project?.id});}
 shell=mountApplicationShell(root,{id:'forge-projects',context:{kind:project?'project':'library',title:project?.title||'Your Projects',revision:revision?'V'+revision.sequence+' · '+revision.name:'',save:project?(pending?'Unsaved editor design awaiting a cloud revision':dirty?'Unsaved metadata / revision draft':'Saved cloud revision'):'Private library · Pro Preview'},views,commands,browser,properties:props,status,help,links:[{text:'Free design',href:deploymentPath('/circuit-forge/')},{text:'Account',href:deploymentPath('/account/')}],onView:view=>{showProperties(view);onView?.(view);}});
 shell.selectView(views.some(v=>v.id===activeView)?activeView:project?'instrument':'library');
 if(project&&metadataForm){const save=e('button','Save cloud revision');save.type='button';save.disabled=project.lifecycle==='ARCHIVED';save.addEventListener('click',()=>{shell.selectView('instrument');if(metadataForm.checkValidity())metadataForm.requestSubmit();else{shell.openPanel('properties');metadataForm.reportValidity();}});shell.appbar.append(save);metadataForm.addEventListener('input',()=>shell.setContext({save:'Unsaved metadata / revision draft'}));metadataForm.addEventListener('change',()=>shell.setContext({save:'Unsaved metadata / revision draft'}));}
 function inspect(kind,data){inspection.replaceChildren();caption.textContent='Properties / '+kind;if(metadataForm)metadataForm.hidden=true;for(const [name,value] of Object.entries(data))if(value!=null){const row=e('p',name+': '+(typeof value==='object'?JSON.stringify(value):String(value)));inspection.append(row);}shell.setSelection({kind,id:data.id});shell.openPanel('properties');}
 for(const b of root.querySelectorAll('[data-inspect-revision]'))b.addEventListener('click',()=>inspect('Revision',JSON.parse(b.dataset.inspectRevision)));
 for(const b of root.querySelectorAll('[data-inspect-measurement]'))b.addEventListener('click',()=>inspect('Measurement',JSON.parse(b.dataset.inspectMeasurement)));
 for(const b of root.querySelectorAll('[data-inspect-component]'))b.addEventListener('click',()=>inspect('Component (saved specification)',JSON.parse(b.dataset.inspectComponent)));
 return shell;
}

export function mountProjectAccessShell({root,status,content,eligible=false}={}){const doc=root.ownerDocument,props=doc.createElement('aside');props.innerHTML='<h2>Properties</h2><p>Private project tools require a confirmed signed-in account and effective capability access.</p>';return mountApplicationShell(root,{id:'forge-access',context:{kind:'access',title:'Forge Projects',save:eligible?'Preview access unavailable':'Sign in to use private projects'},views:[{id:'access',title:'Projects',node:content}],commands:[],browser:[],properties:props,status,links:[{text:'Free design',href:deploymentPath('/circuit-forge/')},{text:'Account',href:deploymentPath('/account/')}]});}
